const platformServiceGuides = [{"slug": "salla-seo-service-scope-ar", "title": "خدمات سيو سلة: ماذا تطلب من متخصص تحسين متجرك؟", "description": "دليل تعاقد عملي لخدمة سيو سلة: فحص الفهرسة، خريطة الكلمات، تحسين المنتجات والتصنيفات، حدود التنفيذ وتقارير تقيس العمل دون وعود ترتيب.", "keyword": "خدمات سيو سلة", "sections": [["ما الذي تحصل عليه من خدمة سيو سلة؟", "خدمة سيو سلة الجيدة ليست تعبئة كلمات في خانات SEO. هي فحص المشاكل المؤثرة في اكتشاف منتجاتك، وتحديد صفحات تستحق الأولوية، ثم تنفيذ تحسينات واضحة داخل حدود منصتك ومتابعتها. قبل الاتفاق مع متخصص، اطلب نطاقًا مكتوبًا يحدد الصفحات والتسليمات والصلاحيات وكيف ستعرف أن العمل تم.", "هذا الدليل يشرح طريقة العمل التي أقدمها، وليس نتيجة متجر عميل أو ضمان ظهور. التفاصيل والعدد الفعلي للمنتجات يتحددان بعد مراجعة المتجر. إذا كان المتجر جديدًا، تختلف الأولويات عن متجر لديه زيارات لكن الطلبات ضعيفة."], ["الفحص الأول: هل المشكلة في الظهور أم في الشراء؟", "ابدأ بعينة من المنتجات والتصنيفات المهمة تجاريًا. افحص إمكانية فتحها دون تسجيل دخول، العنوان والوصف، المحتوى، الروابط إليها، وأي توجيه يمنع الفهرسة. راجع Search Console إن كان متاحًا: وجود صفحة في خريطة الموقع لا يعني أنها مفهرسة، وطلب الفهرسة لا يضمن وقتًا للظهور.", "إذا كانت الصفحة تحصل على نقرات مناسبة لكن لا تتحول لطلبات، راجع المعلومات التي يحتاجها المشتري: المقاسات، الاستخدام، الشحن، الإرجاع والسعر. لا تعالج مشكلة تحويل بتكرار الكلمة المفتاحية. افصل تشخيص السيو عن مشاكل المخزون والتسعير وتجربة الدفع."], ["خريطة كلمات مرتبطة بالمخزون", "الخريطة تربط كل نية بحث بصفحة مناسبة: تصنيف للمقارنة بين منتجات متشابهة، وصفحة منتج للمواصفات والشراء، ودليل شراء عندما يحتاج العميل شرحًا قبل الاختيار. لا تنشئ مقالًا لكل صيغة متقاربة من اسم المنتج؛ قد تكون صفحة واحدة جيدة كافية.", "مثال توضيحي وليس تجربة عميل: متجر قهوة يمكنه تحسين تصنيف ماكينات القهوة للمقارنة، وصفحة ماكينة محددة للمقاس والمواصفات، ودليل اختيار الماكينة للاستخدام المنزلي. اختيار الأولويات يعتمد على المخزون والربح وأسئلة العملاء والاستعلامات الفعلية، لا على حجم بحث مصطنع."], ["التنفيذ في أدوات سلة المتاحة", "توثيق سلة يوضح أدوات لعناوين وأوصاف الصفحة الرئيسية والمنتجات والتصنيفات والماركات، وإعدادات للروابط وخريطة الموقع. خدمة التنفيذ تراجع ما هو متاح في باقتك ولوحتك الحالية أولًا، ثم تسجل ما تغير والسبب والصفحات المتأثرة. لا نعد بصلاحية تعديل كل جزء تقني في منصة مستضافة.", "ابدأ بالصفحات المهمة بدل تعميم عنوان آلي على آلاف المنتجات. اكتب وصفًا دقيقًا يساعد الاختيار، وروابط داخلية مفيدة، وصورًا مناسبة. إذا كان المطلوب يتجاوز أدوات الحساب، نوضح الاحتياج للمطور أو دعم المنصة؛ لا نضيف تطبيقًا مدفوعًا أو اشتراكًا دون اتفاق."], ["كيف تراجع تسليم الخدمة؟", "اطلب سجلًا يتضمن رابط الصفحة، المشكلة، الأولوية، الإجراء المنفذ وطريقة التحقق. اطلب خريطة كلمات وصفحات، وعينة قبل التعديل وبعده، ومشاكل تحتاج صلاحية أو طرفًا آخر. التقرير الذي يعرض قائمة كلمات فقط لا يوضح التنفيذ.", "راقب الظهور والنقرات للاستعلامات المناسبة، والطلبات من الصفحات المحسنة عندما يكون القياس متاحًا. لا تنسب تغير المبيعات كله للسيو: الموسم والإعلانات والخصومات والمخزون قد تغير الأرقام. لا يوجد ترتيب أول أو عدد مبيعات مضمون."], ["خدمة السيو وحدها أم السيو والإعلانات؟", "إذا كانت المشكلة في أساس المتجر، ابدأ بتدقيق وتحسين الصفحات. وإذا احتجت حملات Google أو Meta أيضًا، فإن باقة السيو والإعلانات تضيف إدارة الحملات ومراجعة صفحات الهبوط. ميزانية الإعلان مستقلة عن أتعاب الخدمة. باقة تجهيز المتجر تناسب نطاق بناء وإعداد مختلفًا وليست بديلًا عن إدارة شهرية مستمرة.", "راجع الباقات المنشورة، ثم حدد عدد المنتجات وأهدافك والصلاحيات المتاحة قبل الاتفاق. المراجعة المجانية خطوة لتحديد الاحتياج وليست شهر إدارة مجاني. اختر نطاقًا تستطيع تنفيذه ومراجعته بدل وعد كبير بلا قائمة تسليمات."], ["الظهور في إجابات الذكاء الاصطناعي: تجنب الوعود", "وجود خيار llms.txt في منصة لا يعني أن Google يستخدمه لتحسين ظهورك. إرشادات Google تقول إن ملفات AI الخاصة ليست مطلوبة للبحث. كذلك لم تعد نتائج FAQ المحسنة معروضة؛ الأسئلة المفيدة تساعد القارئ، لكنها ليست وعدًا بالنقرات أو اقتباس الذكاء الاصطناعي.", "الأولوية لمحتوى مفهوم وقابل للوصول، ومعلومات منتج صادقة وبيانات منظمة مطابقة للصفحة. أدوات سلة توضح التحكم المتاح؛ أما شروط الظهور في بحث Google فنراجعها من Google نفسها عند اختلاف النصائح."]], "faq": [{"q": "هل خدمة سيو سلة تشمل كل منتجات المتجر؟", "a": "العدد والنطاق يتحددان بعد الفحص. الاتفاق يجب أن يسمي المنتجات والتصنيفات والأعمال المطلوبة؛ لا تفترض تغطية غير محدودة."}, {"q": "هل سعر الإدارة يشمل الإعلانات أو تطبيقات سلة؟", "a": "ميزانية الإعلانات منفصلة. الاشتراك أو التطبيق المدفوع يتطلب اتفاقًا على التكلفة قبل استخدامه."}], "sources": [["سلة: أدوات تحسين محركات البحث", "https://help.salla.sa/article/%D8%AA%D8%AD%D8%B3%D9%8A%D9%86-%D8%B8%D9%87%D9%88%D8%B1-%D9%85%D8%AA%D8%AC%D8%B1%D9%83-%D8%B9%D9%84%D9%89-%D9%85%D8%AD%D8%B1%D9%83%D8%A7%D8%AA-%D8%A7%D9%84%D8%A8%D8%AD%D8%AB-seo/oi134aj2ud6ts12ysumrm5za"], ["سلة: Search Console", "https://help.salla.sa/article/820644222"], ["Google: إرشادات المحتوى المفيد", "https://developers.google.com/search/docs/fundamentals/creating-helpful-content"], ["Google: البحث بالذكاء الاصطناعي", "https://developers.google.com/search/docs/fundamentals/ai-optimization-guide"], ["Google: تحديثات التوثيق", "https://developers.google.com/search/updates"]]}, {"slug": "zid-seo-audit-service-ar", "title": "أوديت سيو متجر زد: أولويات الإصلاح والتسليم قبل التعاقد", "description": "كيف تفحص متجر زد وتختار إصلاحات السيو ذات الأولوية: الصفحات والمنتجات والتصنيفات والفهرسة ونطاق التنفيذ وتقرير واضح للمالك.", "keyword": "أوديت سيو متجر زد", "sections": [["الأوديت قرار عملي، وليس درجة من أداة", "أوديت سيو متجر زد هو فحص يحدد لماذا لا تكتشف محركات البحث صفحات مهمة أو لماذا لا تخدم الصفحات نية المشتري، ثم يرتب الإصلاحات الممكنة داخل المنصة. القيمة في مشكلة يمكنك إعادة فحصها وإجراء واضح ومسؤول عن التنفيذ؛ ليست في ملف طويل بأخطاء عامة.", "أنا عمرو البصيلي، وأقدم فحص السيو وخريطة الكلمات وتحسين الصفحات ضمن نطاق يتم تحديده بعد مراجعة المتجر. هذا إطار عمل للخدمة، وليس أوديتًا منفذًا على متجر بعينه أو نتيجة مبيعات مضمونة."], ["ابدأ بالمعلومات التي تغير الأولويات", "اسأل المالك عن الفئات المهمة، المنتجات المتاحة، مناطق الشحن، هوامش الربح وأهم أسئلة العملاء. اجمع روابط عينة وصفحات تتلقى زيارات فعلية عندما تتوفر بيانات. اسم المنصة وحده لا يثبت أن المشكلة واحدة في كل المتاجر.", "راجع الصلاحيات والخطة الحالية: هل يمكن الوصول إلى إعدادات SEO وSearch Console والتحليلات؟ ما الذي يديره طرف آخر؟ لا تطلب كلمة مرور في رسالة؛ استخدم طريقة وصول آمنة أو صلاحيات مناسبة، واتفق على من يعتمد التغييرات ومتى."], ["قسّم الفحص إلى أربعة أنواع صفحات", "توثيق زد يذكر تحسين الصفحة الرئيسية والمنتجات والتصنيفات والصفحات الإضافية. افحص عينة من كل نوع: الصفحة الرئيسية تشرح نشاط المتجر، والتصنيف يسهل المقارنة، والمنتج يوضح عرضًا محددًا، وصفحات السياسات تجيب عن أسئلة الثقة والشحن.", "لا تستهدف نفس الكلمة في كل العناوين. مثال توضيحي: تصنيف عطور عود يوضح خيارات الفئة، بينما منتج بعينه يذكر الحجم والمكونات والمواصفات المؤكدة. صفحة سياسة الشحن لا تحتاج عنوانًا محشوًا باسم المنتج. توزيع النية يمنع تضارب الصفحات ويخدم الزائر."], ["إعدادات المنتجات: دقة قبل كثرة", "مركز مساعدة زد يوضح حقول عنوان المنتج ووصف الصفحة ورابطها، مع استخدام معلومات أساسية تلقائيًا إذا لم تعبأ الحقول. الفحص يراجع الناتج الفعلي، لا يفترض أن النص التلقائي مناسب لكل منتج. ابدأ بالمنتجات المهمة والمتاحة، ثم توسع حسب نطاق الاتفاق.", "قبل تغيير رابط منتج قائم، راجع الروابط الداخلية والزيارات وإمكانية الحفاظ على وصول الزائر. لا تغيّر كل الروابط لمجرد جعلها أقصر، ولا تعد بإعدادات إعادة توجيه غير متحقق منها في حسابك. إن احتاج التنفيذ دعم المنصة، يسجل التقرير هذا الاحتياج بوضوح."], ["الفهرسة وخريطة الموقع والبيانات المنظمة", "قارن الصفحات التجارية المهمة مع التقارير المتاحة في Search Console، وافحص الروابط الفردية عند الحاجة. خريطة الموقع تساعد الاكتشاف لكنها لا تضمن الفهرسة. الصفحة التي لا يظهر لها طلب أو محتوى مفيد ليست أولوية لمجرد وجودها في الكتالوج.", "افحص سعر وتوفر منتج فعلي والبيانات المنظمة الناتجة، خاصة عند التخفيض أو اختلاف المقاسات. يجب ألا تتعارض المعلومات مع ما يراه المشتري. لا نضيف ترميزًا مكررًا أو تقييمات وهمية للحصول على شارة؛ صحة الترميز لا تضمن أن Google سيعرض نتيجة محسنة."], ["رتب الإصلاحات على أساس الأثر وإمكانية التنفيذ", "المرتبة الأولى لمشكلة تمنع الوصول إلى صفحة تجارية مهمة أو تعرض معلومة شراء خاطئة. بعدها المعلومات الناقصة والعناوين والروابط الداخلية وتحسين تجربة الهاتف. ضع أمام كل مشكلة: الدليل، الصفحة، الأولوية، الإجراء، من ينفذه وكيف نتحقق.", "مثال توضيحي: منتج متاح لا يمكن الوصول إليه من تصنيفه يحتاج إصلاح مسار الاكتشاف قبل مقال عام جديد. تصنيف مفيد بوصف ضعيف قد يحتاج معلومات مقارنة. نتيجة أداة سرعة ليست وحدها سببًا لتغيير القالب؛ افحص تجربة المستخدم وما تستطيع المنصة التحكم فيه."], ["ماذا تطلب في نهاية الأوديت؟", "التسليم المفيد يشمل عينة موثقة للمشاكل، خريطة صفحات وكلمات، قائمة إصلاحات مرتبة، سجل التنفيذ وحدود الصلاحيات وخطة متابعة. افصل بين عمل الفحص وعمل الإصلاح في الاتفاق، ووضح أي احتياج لدعم زد أو مطور أو تطبيق مدفوع.", "التحسن يقاس ببيانات فعلية عندما تتوفر: الظهور للاستعلامات المناسبة والنقرات والطلبات. لا يوجد موعد واحد مضمون للنتائج؛ سرعة الزحف والمنافسة والمخزون وعوامل أخرى تؤثر. لا تتحول مدة منشورة في دليل عام إلى وعد تعاقدي لمتجرك."], ["اختيار نطاق الخدمة مع عمرو البصيلي", "باقة تأسيس السيو تشمل التدقيق وبحث الكلمات وتحسين الصفحات الأساسية والقياس والتقرير. باقة السيو والإعلانات تضيف حملات Google وMeta، بينما تجهيز متجر جديد له نطاق مختلف. الأسعار الحالية موجودة في صفحة الباقات بدل نسخ رقم قد يتغير داخل كل مقال.", "أرسل رابط المتجر وهدفك وعدد المنتجات التقريبي لبدء مراجعة الاحتياج. لا تختار أوديتًا لأن المنافس يبيع المصطلح؛ اختره إذا كنت تحتاج تشخيصًا واضحًا أو خطة تنفيذ يمكن متابعة تسليمها. ميزانية الحملات واشتراك المنصة وأي تطبيق مدفوع يناقش كل منها على حدة."]], "faq": [{"q": "هل أوديت زد يعني ضمان فهرسة كل المنتجات؟", "a": "لا. الأوديت يكشف المشاكل ويرتب العمل؛ قرار الفهرسة والظهور عند Google ولا يوجد ضمان لكل منتج."}, {"q": "هل يجب تغيير كل روابط المنتجات أثناء الأوديت؟", "a": "لا. تغيير الروابط قرار له آثار على الوصول والروابط القائمة ويحتاج فحصًا؛ ليس إجراءً تلقائيًا لكل متجر."}], "sources": [["زد: إعدادات SEO المتجر", "https://help.zid.sa/seo-store/"], ["زد: تحسين صفحات المنتجات", "https://help.zid.sa/seo-products/"], ["Google: بنية متاجر إلكترونية", "https://developers.google.com/search/docs/specialty/ecommerce/help-google-understand-your-ecommerce-site-structure"], ["Google: المحتوى المفيد", "https://developers.google.com/search/docs/fundamentals/creating-helpful-content"]]}] as const;
